1	package com.shy.nexusix.iam.service.impl;
2	
3	import cn.dev33.satoken.stp.StpUtil;
4	import com.alibaba.fastjson2.JSON;
5	import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
6	import com.shy.nexusix.common.constant.GlobalConstant;
7	import com.shy.nexusix.common.enums.GlobalEnum;
8	import com.shy.nexusix.common.exception.BusinessException;
9	import com.shy.nexusix.common.result.ApiResponse;
10	import com.shy.nexusix.core.entity.dto.UserContextDTO;
11	import com.shy.nexusix.iam.dto.UserDeptDTO;
12	import com.shy.nexusix.iam.dto.UserPermDTO;
13	import com.shy.nexusix.iam.dto.UserRoleDTO;
14	import com.shy.nexusix.iam.dto.UserTenantItemDTO;
15	import com.shy.nexusix.iam.entity.SysUser;
16	import com.shy.nexusix.iam.mapper.SysPermPolicyMapper;
17	import com.shy.nexusix.iam.mapper.SysUserMapper;
18	import com.shy.nexusix.iam.mapper.SysUserPolicyMapper;
19	import com.shy.nexusix.iam.rto.LoginRTO;
20	import com.shy.nexusix.iam.service.IAuthService;
21	import org.springframework.beans.factory.annotation.Autowired;
22	import org.springframework.stereotype.Service;
23	
24	import java.time.LocalDateTime;
25	import java.util.*;
26	
27	/**
28	 * <p>认证服务实现类</p>
29	 *
30	 * @author shy
31	 * @since 2026-06-12
32	 */
33	@Service
34	public class AuthServiceImpl implements IAuthService {
35	
36	    @Autowired
37	    private SysUserMapper sysUserMapper;
38	
39	    @Autowired
40	    private SysUserPolicyMapper sysUserPolicyMapper;
41	
42	    @Autowired
43	    private SysPermPolicyMapper sysPermPolicyMapper;
44	
45	    /**
46	     * 用户登录
47	     * <p>
48	     * 执行用户认证流程，包括：用户校验、租户验证、权限查询、上下文构建
49	     * </p>
50	     *
51	     * @param param 登录请求参数（用户名、密码）
52	     * @return 包含用户上下文信息的响应
53	     * @throws BusinessException 当用户不存在、已禁用、未关联租户或租户已禁用时抛出
54	     */
55	    @Override
56	    public ApiResponse login(LoginRTO param) {
57	
58	        // 检查当前用户是否已经登录
59	        if (StpUtil.isLogin(param.getUsername())) {
60	            return ApiResponse.success("用户已登录");
61	        }
62	
63	        // 校验用户名是否存在
64	        SysUser user = sysUserMapper.selectOne(new LambdaQueryWrapper<SysUser>()
65	                .eq(SysUser::getUserName, param.getUsername())
66	                .eq(SysUser::getIsDeleted, GlobalEnum.Deleted.NOT_DELETED.getCode()));
67	
68	        if (user == null) {
69	            throw new BusinessException("用户不存在");
70	        }
71	
72	        // 校验用户状态
73	        if ("DISABLED".equals(user.getStatus())) {
74	            throw new BusinessException("用户已被禁用");
75	        }
76	        if ("LOCKED".equals(user.getStatus())) {
77	            throw new BusinessException("用户已被锁定");
78	        }
79	
80	        // TODO: 校验密码是否匹配（后续使用加密对比）
81	        // if (!passwordEncoder.matches(param.getPassword(), user.getPassword())) {
82	        //     throw new BusinessException("密码错误");
83	        // }
84	
85	        // 查询用户所有租户信息
86	        List<UserTenantItemDTO> tenantList = sysUserPolicyMapper.queryUserAllTenantInfo(user.getId());
87	
88	        // 校验无租户关联则不允许登录
89	        if (tenantList == null || tenantList.isEmpty()) {
90	            throw new BusinessException("用户未关联任何租户，无法登录");
91	        }
92	
93	        // 确定当前登录租户（优先主租户）
94	        UserTenantItemDTO currentTenant = null;
95	        for (UserTenantItemDTO tenant : tenantList) {
96	            if (Boolean.TRUE.equals(tenant.getIsPrimary())) {
97	                currentTenant = tenant;
98	                break;
99	            }
100	        }
101	        if (currentTenant == null) {
102	            currentTenant = tenantList.get(0);
103	        }
104	
105	        // 校验当前租户是否处于停用状态
106	        if ("DISABLED".equals(currentTenant.getStatus())) {
107	            throw new BusinessException("当前租户已禁用，无法登录");
108	        }
109	
110	        // 校验当前租户是否已过期
111	        if (currentTenant.getExpireTime() != null
112	            && LocalDateTime.now().isAfter(currentTenant.getExpireTime())) {
113	            throw new BusinessException("租户服务已过期，无法登录");
114	        }
115	
116	        // 执行登录操作
117	        // StpUtil.login(user.getId());
118	
119	        // 更新最后登录时间和IP（UPDATE操作）
120	        user.setLastLoginAt(LocalDateTime.now());
121	        // user.setLastLoginIp(获取真实IP); // 从请求中获取
122	        sysUserMapper.updateById(user);
123	
124	        // 查询用户所有权限信息
125	        List<UserPermDTO> permList = sysPermPolicyMapper.queryUserAllPermInfo(user.getId());
126	
127	        // 构建权限信息对象
128	        UserContextDTO.PermissionInfo permissionInfo = new UserContextDTO.PermissionInfo();
129	        Set<String> allPermCodeSet = new LinkedHashSet<>();
130	        List<String> validPermCodeList = new ArrayList<>();
131	        List<String> invalidPermCodeList = new ArrayList<>();
132	
133	        // 字段级权限映射，按操作类型分组（查询/创建/更新）
134	        Map<String, UserContextDTO.TableFieldPermission> queryFieldMap = new HashMap<>();
135	        Map<String, UserContextDTO.TableFieldPermission> createFieldMap = new HashMap<>();
136	        Map<String, UserContextDTO.TableFieldPermission> updateFieldMap = new HashMap<>();
137	
138	        // 遍历所有权限记录，提取权限编码和字段级权限（优化：减少嵌套循环和重复操作）
139	        for (UserPermDTO perm : permList) {
140	            if (perm.getPermCode() == null) {
141	                continue;
142	            }
143	
144	            // 权限编码去重
145	            allPermCodeSet.add(perm.getPermCode());
146	
147	            // 根据权限策略状态分类权限编码
148	            boolean isActive = "ACTIVE".equals(perm.getPermPolicyStatus());
149	            if (isActive) {
150	                validPermCodeList.add(perm.getPermCode());
151	            } else {
152	                invalidPermCodeList.add(perm.getPermCode());
153	            }
154	
155	            // 解析字段级权限（JSON格式：{"user_name":["READ","CREATE","UPDATE"], "email":["READ","UPDATE"]}）
156	            if (perm.getFieldPermissions() != null && !perm.getFieldPermissions().isEmpty()
157	                && perm.getTableName() != null) {
158	                try {
159	                    Map<String, List<String>> fieldMap = JSON.parseObject(
160	                        perm.getFieldPermissions(),
161	                        Map.class
162	                    );
163	
164	                    if (fieldMap != null && !fieldMap.isEmpty()) {
165	                        String tableName = perm.getTableName();
166	
167	                        // 预先获取或创建三个操作类型的表字段权限对象，避免在循环中重复computeIfAbsent
168	                        UserContextDTO.TableFieldPermission queryTablePerm = null;
169	                        UserContextDTO.TableFieldPermission createTablePerm = null;
170	                        UserContextDTO.TableFieldPermission updateTablePerm = null;
171	
172	                        // 遍历每个字段及其操作类型
173	                        for (Map.Entry<String, List<String>> entry : fieldMap.entrySet()) {
174	                            String fieldName = entry.getKey();
175	                            List<String> operations = entry.getValue();
176	
177	                            if (operations == null || operations.isEmpty()) {
178	                                continue;
179	                            }
180	
181	                            // 处理READ操作，映射到查询权限
182	                            if (operations.contains("READ")) {
183	                                if (queryTablePerm == null) {
184	                                    queryTablePerm = queryFieldMap.computeIfAbsent(tableName,
185	                                        k -> new UserContextDTO.TableFieldPermission());
186	                                }
187	
188	                                // 黑名单机制：只要有一个来源是DISABLED，字段就不可操作
189	                                if (!isActive) {
190	                                    if (!queryTablePerm.getInoperable().contains(fieldName)) {
191	                                        queryTablePerm.getInoperable().add(fieldName);
192	                                    }
193	                                    queryTablePerm.getOperable().remove(fieldName);
194	                                } else {
195	                                    if (!queryTablePerm.getInoperable().contains(fieldName)
196	                                        && !queryTablePerm.getOperable().contains(fieldName)) {
197	                                        queryTablePerm.getOperable().add(fieldName);
198	                                    }
199	                                }
200	                            }
201	
202	                            // 处理CREATE操作，映射到创建权限
203	                            if (operations.contains("CREATE")) {
204	                                if (createTablePerm == null) {
205	                                    createTablePerm = createFieldMap.computeIfAbsent(tableName,
206	                                        k -> new UserContextDTO.TableFieldPermission());
207	                                }
208	
209	                                // 黑名单机制：只要有一个来源是DISABLED，字段就不可操作
210	                                if (!isActive) {
211	                                    if (!createTablePerm.getInoperable().contains(fieldName)) {
212	                                        createTablePerm.getInoperable().add(fieldName);
213	                                    }
214	                                    createTablePerm.getOperable().remove(fieldName);
215	                                } else {
216	                                    if (!createTablePerm.getInoperable().contains(fieldName)
217	                                        && !createTablePerm.getOperable().contains(fieldName)) {
218	                                        createTablePerm.getOperable().add(fieldName);
219	                                    }
220	                                }
221	                            }
222	
223	                            // 处理UPDATE操作，映射到更新权限
224	                            if (operations.contains("UPDATE")) {
225	                                if (updateTablePerm == null) {
226	                                    updateTablePerm = updateFieldMap.computeIfAbsent(tableName,
227	                                        k -> new UserContextDTO.TableFieldPermission());
228	                                }
229	
230	                                // 黑名单机制：只要有一个来源是DISABLED，字段就不可操作
231	                                if (!isActive) {
232	                                    if (!updateTablePerm.getInoperable().contains(fieldName)) {
233	                                        updateTablePerm.getInoperable().add(fieldName);
234	                                    }
235	                                    updateTablePerm.getOperable().remove(fieldName);
236	                                } else {
237	                                    if (!updateTablePerm.getInoperable().contains(fieldName)
238	                                        && !updateTablePerm.getOperable().contains(fieldName)) {
239	                                        updateTablePerm.getOperable().add(fieldName);
240	                                    }
241	                                }
242	                            }
243	                        }
244	                    }
245	                } catch (Exception e) {
246	                    // 解析失败，忽略该字段权限
247	                }
248	            }
249	        }
250	
251	        // 设置权限编码列表
252	        permissionInfo.setAll(new ArrayList<>(allPermCodeSet));
253	        permissionInfo.setValid(validPermCodeList);
254	        permissionInfo.setInvalid(invalidPermCodeList);
255	
256	        // 设置字段级权限
257	        UserContextDTO.FieldPermission fieldPermission = new UserContextDTO.FieldPermission();
258	        fieldPermission.setQuery(queryFieldMap);
259	        fieldPermission.setCreate(createFieldMap);
260	        fieldPermission.setUpdate(updateFieldMap);
261	        permissionInfo.setFieldPermission(fieldPermission);
262	
263	        // 初始化禁用详情（初始化为空）
264	        UserContextDTO.DisabledDetail disabledDetail = new UserContextDTO.DisabledDetail();
265	        disabledDetail.setSystem(new ArrayList<>());
266	        disabledDetail.setTenant(new ArrayList<>());
267	        disabledDetail.setRole(new ArrayList<>());
268	        disabledDetail.setUser(new ArrayList<>());
269	        permissionInfo.setDisabledDetail(disabledDetail);
270	
271	        // 查询用户所有部门信息
272	        List<UserDeptDTO> deptList = sysUserPolicyMapper.queryUserAllDeptInfo(user.getId());
273	
274	        // 构建部门分组信息（优化：一次遍历完成所有分组）
275	        UserContextDTO.DeptGroup deptGroup = new UserContextDTO.DeptGroup();
276	        List<UserContextDTO.DeptItem> currentDepts = new ArrayList<>();
277	        List<UserContextDTO.DeptItem> allDepts = new ArrayList<>();
278	        List<UserContextDTO.DeptItem> validDeptItems = new ArrayList<>();
279	        List<UserContextDTO.DeptItem> invalidDeptItems = new ArrayList<>();
280	
281	        String currentTenantCode = currentTenant.getTenantCode();
282	        for (UserDeptDTO dto : deptList) {
283	            if (dto.getDeptCode() == null) {
284	                continue;
285	            }
286	
287	            UserContextDTO.DeptItem item = new UserContextDTO.DeptItem();
288	            item.setDeptCode(dto.getDeptCode());
289	            item.setDeptName(dto.getDeptName());
290	            item.setPath(dto.getPath());
291	            item.setLevel(dto.getLevel());
292	            item.setTenantCode(dto.getTenantCode());
293	            item.setTenantName(dto.getTenantName());
294	            item.setIsPrimary(dto.getIsPrimary());
295	            item.setUserPolicyStatus(dto.getUserPolicyStatus());
296	
297	            allDepts.add(item);
298	
299	            if (currentTenantCode != null && currentTenantCode.equals(dto.getTenantCode())) {
300	                currentDepts.add(item);
301	            }
302	
303	            if ("ACTIVE".equals(dto.getUserPolicyStatus())) {
304	                validDeptItems.add(item);
305	            } else {
306	                invalidDeptItems.add(item);
307	            }
308	        }
309	
310	        deptGroup.setCurrent(currentDepts);
311	        deptGroup.setAll(allDepts);
312	        deptGroup.setValid(validDeptItems);
313	        deptGroup.setInvalid(invalidDeptItems);
314	
315	        // 查询用户所有角色信息
316	        List<UserRoleDTO> roleList = sysUserPolicyMapper.queryUserAllRoleInfo(user.getId());
317	
318	        // 构建角色分组信息（优化：一次遍历完成所有分组）
319	        UserContextDTO.RoleGroup roleGroup = new UserContextDTO.RoleGroup();
320	        List<UserContextDTO.RoleItem> currentRoles = new ArrayList<>();
321	        List<UserContextDTO.RoleItem> allRoles = new ArrayList<>();
322	        List<UserContextDTO.RoleItem> validRoleItems = new ArrayList<>();
323	        List<UserContextDTO.RoleItem> invalidRoleItems = new ArrayList<>();
324	
325	        for (UserRoleDTO dto : roleList) {
326	            if (dto.getRoleCode() == null) {
327	                continue;
328	            }
329	
330	            UserContextDTO.RoleItem item = new UserContextDTO.RoleItem();
331	            item.setRoleCode(dto.getRoleCode());
332	            item.setDataScope(dto.getDataScope() != null ? dto.getDataScope() : "SELF");
333	            item.setTenantCode(dto.getTenantCode());
334	            item.setTenantName(dto.getTenantName());
335	
336	            allRoles.add(item);
337	
338	            if (currentTenantCode != null && currentTenantCode.equals(dto.getTenantCode())) {
339	                currentRoles.add(item);
340	            }
341	
342	            if ("ACTIVE".equals(dto.getRolePolicyStatus())) {
343	                validRoleItems.add(item);
344	            } else {
345	                invalidRoleItems.add(item);
346	            }
347	        }
348	
349	        roleGroup.setCurrent(currentRoles);
350	        roleGroup.setAll(allRoles);
351	        roleGroup.setValid(validRoleItems);
352	        roleGroup.setInvalid(invalidRoleItems);
353	
354	        // 构建租户分组信息（优化：一次遍历完成所有分组）
355	        UserContextDTO.TenantGroup tenantGroup = new UserContextDTO.TenantGroup();
356	        List<UserContextDTO.TenantItem> currentTenantList = new ArrayList<>();
357	        List<UserContextDTO.TenantItem> allTenants = new ArrayList<>();
358	        List<UserContextDTO.TenantItem> validTenants = new ArrayList<>();
359	        List<UserContextDTO.TenantItem> invalidTenants = new ArrayList<>();
360	
361	        for (UserTenantItemDTO dto : tenantList) {
362	            UserContextDTO.TenantItem item = new UserContextDTO.TenantItem();
363	            item.setTenantCode(dto.getTenantCode());
364	            item.setTenantName(dto.getTenantName());
365	            item.setStatus(dto.getStatus());
366	            item.setExpireTime(dto.getExpireTime() != null ? dto.getExpireTime().toString() : null);
367	            item.setIsPrimary(dto.getIsPrimary());
368	
369	            allTenants.add(item);
370	
371	            if (dto.getTenantCode().equals(currentTenant.getTenantCode())) {
372	                currentTenantList.add(item);
373	            }
374	
375	            if ("ACTIVE".equals(dto.getStatus())) {
376	                validTenants.add(item);
377	            } else {
378	                invalidTenants.add(item);
379	            }
380	        }
381	
382	        tenantGroup.setCurrent(currentTenantList);
383	        tenantGroup.setAll(allTenants);
384	        tenantGroup.setValid(validTenants);
385	        tenantGroup.setInvalid(invalidTenants);
386	
387	        // 组装用户上下文对象
388	        UserContextDTO userContext = new UserContextDTO();
389	
390	        // 设置用户基本信息
391	        UserContextDTO.UserInfo userInfo = new UserContextDTO.UserInfo();
392	        userInfo.setUserId(user.getId());
393	        userInfo.setUserCode(user.getUserCode());
394	        userInfo.setUserName(user.getUserName());
395	        userInfo.setNickName(user.getNickName());
396	        userInfo.setEmail(user.getEmail());
397	        userInfo.setPhone(user.getPhone());
398	        userInfo.setAvatar(user.getAvatarUrl());
399	        userContext.setUserInfo(userInfo);
400	
401	        // 设置租户分组
402	        userContext.setTenantInfo(tenantGroup);
403	
404	        // 设置权限信息
405	        userContext.setPermInfo(permissionInfo);
406	
407	        // 设置角色分组
408	        userContext.setRoleInfo(roleGroup);
409	
410	        // 设置部门分组
411	        userContext.setDeptInfo(deptGroup);
412	
413	        // 存入Session
414	        // StpUtil.getSession().set(GlobalConstant.Session.USER_CONTEXT, userContext);
415	
416	        return ApiResponse.success("登录成功", userContext);
417	    }
418	
419	}
