1	package com.shy.nexusix.core.entity.dto;
2	
3	import lombok.Data;
4	
5	import java.util.ArrayList;
6	import java.util.List;
7	import java.util.Map;
8	
9	/**
10	 * <p>用户上下文DTO，登录时构建并存入Sa-Token Session</p>
11	 *
12	 * <pre>
13	 * 结构概览：
14	 *   userInfo          — 用户基本信息
15	 *   tenantInfo        — 租户分组（当前/全部/有效/无效）
16	 *   permInfo          — 权限汇总（全部/有效/无效 + 级联禁用详情 + 字段级权限）
17	 *   roleInfo          — 角色分组（当前租户/全部/有效/无效），每条角色标注所属租户
18	 *   deptInfo          — 部门分组（当前租户/全部/有效/无效），每条部门标注所属租户
19	 * </pre>
20	 *
21	 * @author shy
22	 * @since 2026-06-11
23	 */
24	@Data
25	public class UserContextDTO {
26	
27	    /** 用户基本信息 */
28	    private UserInfo userInfo;
29	
30	    /** 租户分组（当前/全部/有效/无效） */
31	    private TenantGroup tenantInfo;
32	
33	    /** 权限汇总信息 */
34	    private PermissionInfo permInfo;
35	
36	    /** 角色分组（当前租户/全部/有效/无效），含租户标注 */
37	    private RoleGroup roleInfo;
38	
39	    /** 部门分组（当前租户/全部/有效/无效），含租户标注 */
40	    private DeptGroup deptInfo;
41	
42	    // ==================== 用户信息 ====================
43	
44	    @Data
45	    public static class UserInfo {
46	        /** 用户ID */
47	        private Long userId;
48	        /** 用户编码 */
49	        private String userCode;
50	        /** 用户名（登录名） */
51	        private String userName;
52	        /** 昵称 */
53	        private String nickName;
54	        /** 邮箱 */
55	        private String email;
56	        /** 手机号 */
57	        private String phone;
58	        /** 头像URL */
59	        private String avatar;
60	    }
61	
62	    // ==================== 租户相关 ====================
63	
64	    @Data
65	    public static class TenantItem {
66	        /** 租户编码 */
67	        private String tenantCode;
68	        /** 租户名称 */
69	        private String tenantName;
70	        /** 租户状态（ENABLED/DISABLED/EXPIRED/PENDING） */
71	        private String status;
72	        /** 服务过期时间 */
73	        private String expireTime;
74	        /** 是否主租户 */
75	        private Boolean isPrimary;
76	    }
77	
78	    @Data
79	    public static class TenantGroup {
80	        /** 当前登录租户 */
81	        private List<TenantItem> current;
82	        /** 全部租户（有效+无效） */
83	        private List<TenantItem> all;
84	        /** 有效租户（用户策略ENABLED 且 租户ENABLED） */
85	        private List<TenantItem> valid;
86	        /** 无效租户（用户策略或租户状态非ENABLED） */
87	        private List<TenantItem> invalid;
88	    }
89	
90	    // ==================== 权限相关 ====================
91	
92	    @Data
93	    public static class PermissionInfo {
94	        /** 全部权限编码（有效+无效，已去重） */
95	        private List<String> all;
96	        /** 有效权限编码（策略ACTIVE且未被任何级别禁用） */
97	        private List<String> valid;
98	        /** 无效权限编码（被系统/租户/角色/用户任一级别禁用） */
99	        private List<String> invalid;
100	        /** 级联禁用详情，按四级分类 */
101	        private DisabledDetail disabledDetail;
102	        /** 字段级权限，按操作类型分组 */
103	        private FieldPermission fieldPermission;
104	    }
105	
106	    @Data
107	    public static class DisabledDetail {
108	        /** 系统级禁用的权限编码 */
109	        private List<String> system;
110	        /** 租户级禁用的权限编码 */
111	        private List<String> tenant;
112	        /** 角色级禁用的权限编码 */
113	        private List<String> role;
114	        /** 用户级禁用的权限编码 */
115	        private List<String> user;
116	    }
117	
118	    @Data
119	    public static class FieldPermission {
120	        /** 查询操作的字段权限，key=表名 */
121	        private Map<String, TableFieldPermission> query;
