1	package com.shy.nexusix.core.entity.dto;
2	
3	import lombok.Data;
4	
5	import java.util.ArrayList;
6	import java.util.List;
7	import java.util.Map;
8	
9	/**
10	 * <p>用户上下文DTO，登录时构建并存入Sa-Token Session</p>
11	 *
12	 * <pre>
13	 * 结构概览：
14	 *   userInfo          — 用户基本信息
15	 *   tenantInfo        — 租户分组（当前/全部/有效/无效）
16	 *   permInfo          — 权限汇总（全部/有效/无效 + 级联禁用详情 + 字段级权限）
17	 *   roleInfo          — 角色分组（当前租户/全部/有效/无效），每条角色标注所属租户
18	 *   deptInfo          — 部门分组（当前租户/全部/有效/无效），每条部门标注所属租户
19	 * </pre>
20	 *
21	 * @author shy
22	 * @since 2026-06-11
23	 */
24	@Data
25	public class UserContextDTO {
26	
27	    /** 用户基本信息 */
28	    private UserInfo userInfo;
29	
30	    /** 租户分组（当前/全部/有效/无效） */
31	    private TenantGroup tenantInfo;
32	
33	    /** 权限汇总信息 */
34	    private PermissionInfo permInfo;
35	
36	    /** 角色分组（当前租户/全部/有效/无效），含租户标注 */
37	    private RoleGroup roleInfo;
38	
39	    /** 部门分组（当前租户/全部/有效/无效），含租户标注 */
40	    private DeptGroup deptInfo;
41	
42	    // ==================== 用户信息 ====================
43	
44	    @Data
45	    public static class UserInfo {
46	        /** 用户ID */
47	        private Long userId;
48	        /** 用户编码 */
49	        private String userCode;
50	        /** 用户名（登录名） */
51	        private String userName;
52	        /** 昵称 */
53	        private String nickName;
54	        /** 邮箱 */
55	        private String email;
56	        /** 手机号 */
57	        private String phone;
58	        /** 头像URL */
59	        private String avatar;
60	    }
61	
62	    // ==================== 租户相关 ====================
63	
64	    @Data
65	    public static class TenantItem {
66	        /** 租户编码 */
67	        private String tenantCode;
68	        /** 租户名称 */
69	        private String tenantName;
70	        /** 租户状态（ENABLED/DISABLED/EXPIRED/PENDING） */
71	        private String status;
72	        /** 服务过期时间 */
73	        private String expireTime;
74	        /** 是否主租户 */
75	        private Boolean isPrimary;
76	    }
77	
78	    @Data
79	    public static class TenantGroup {
80	        /** 当前登录租户 */
81	        private List<TenantItem> current;
82	        /** 全部租户（有效+无效） */
83	        private List<TenantItem> all;
84	        /** 有效租户（用户策略ENABLED 且 租户ENABLED） */
85	        private List<TenantItem> valid;
86	        /** 无效租户（用户策略或租户状态非ENABLED） */
87	        private List<TenantItem> invalid;
88	    }
89	
90	    // ==================== 权限相关 ====================
91	
92	    @Data
93	    public static class PermItem {
94	        /** 权限编码 */
95	        private String permCode;
96	        /** 权限名称 */
97	        private String permName;
98	        /** 权限类型：MENU, BUTTON, API, DATA */
99	        private String permType;
100	        /** 所属租户编码 */
101	        private String tenantCode;
102	        /** 所属租户名称 */
103	        private String tenantName;
104	        /** 权限策略状态（ACTIVE/DISABLED） */
105	        private String permPolicyStatus;
106	    }
107	
108	    @Data
109	    public static class PermissionInfo {
110	        /** 当前登录租户下的权限列表（无论启用还是禁用） */
111	        private List<PermItem> current = new ArrayList<>();
112	        /** 全部权限（跨所有租户，含有效+无效） */
113	        private List<PermItem> all = new ArrayList<>();
114	        /** 有效权限（权限策略状态为ACTIVE） */
115	        private List<PermItem> valid = new ArrayList<>();
116	        /** 无效权限（权限策略状态非ACTIVE） */
117	        private List<PermItem> invalid = new ArrayList<>();
118	        /** 级联禁用详情，按四级分类 */
119	        private DisabledDetail disabledDetail;
120	        /** 字段级权限，按操作类型分组 */
121	        private FieldPermission fieldPermission;
122	    }
123	
124	    @Data
125	    public static class DisabledDetail {
126	        /** 系统级禁用的权限编码 */
127	        private List<String> system;
128	        /** 租户级禁用的权限编码 */
129	        private List<String> tenant;
130	        /** 角色级禁用的权限编码 */
131	        private List<String> role;
132	        /** 用户级禁用的权限编码 */
133	        private List<String> user;
134	    }
135	
136	    @Data
137	    public static class FieldPermission {
138	        /** 查询操作的字段权限，key=表名 */
139	        private Map<String, TableFieldPermission> query;
140	        /** 创建操作的字段权限，key=表名 */
141	        private Map<String, TableFieldPermission> create;
142	        /** 更新操作的字段权限，key=表名 */
143	        private Map<String, TableFieldPermission> update;
144	    }
145	
146	    @Data
147	    public static class TableFieldPermission {
148	        /** 可操作字段列表（策略ACTIVE时配置） */
149	        private List<String> operable = new ArrayList<>();
150	        /** 不可操作字段列表（策略非ACTIVE时配置） */
151	        private List<String> inoperable = new ArrayList<>();
152	    }
153	
154	    // ==================== 角色相关 ====================
155	
156	    @Data
157	    public static class RoleItem {
158	        /** 角色编码 */
159	        private String roleCode;
160	        /** 角色名称 */
161	        private String roleName;
162	        /** 数据权限范围（ALL/DEPT/DEPT_AND_SUB/SELF） */
163	        private String dataScope;
164	        /** 所属租户编码 */
165	        private String tenantCode;
166	        /** 所属租户名称 */
167	        private String tenantName;
168	    }
169	
170	    @Data
171	    public static class RoleGroup {
172	        /** 当前登录租户下的角色列表 */
173	        private List<RoleItem> current = new ArrayList<>();
174	        /** 全部角色（跨所有租户，含有效+无效） */
175	        private List<RoleItem> all = new ArrayList<>();
176	        /** 有效角色（角色策略状态为ACTIVE） */
177	        private List<RoleItem> valid = new ArrayList<>();
178	        /** 无效角色（角色策略状态非ACTIVE） */
179	        private List<RoleItem> invalid = new ArrayList<>();
180	    }
181	
182	    // ==================== 部门相关 ====================
183	
184	    @Data
185	    public static class DeptItem {
186	        /** 部门编码 */
187	        private String deptCode;
188	        /** 部门名称 */
189	        private String deptName;
190	        /** 部门路径 */
191	        private String path;
192	        /** 层级深度 */
193	        private Integer level;
194	        /** 所属租户编码 */
195	        private String tenantCode;
196	        /** 所属租户名称 */
197	        private String tenantName;
198	        /** 是否主部门 */
199	        private Boolean isPrimary;
200	        /** 用户策略状态（ACTIVE/DISABLED） */
201	        private String userPolicyStatus;
202	    }
203	
204	    @Data
205	    public static class DeptGroup {
206	        /** 当前登录租户下的部门列表 */
207	        private List<DeptItem> current = new ArrayList<>();
208	        /** 全部部门（跨所有租户，含有效+无效） */
209	        private List<DeptItem> all = new ArrayList<>();
210	        /** 有效部门（用户策略状态为ACTIVE） */
211	        private List<DeptItem> valid = new ArrayList<>();
212	        /** 无效部门（用户策略状态非ACTIVE） */
213	        private List<DeptItem> invalid = new ArrayList<>();
214	    }
215	
216	}

