17	 *   roleInfo          — 角色分组（当前租户/全部/有效/无效），每条角色标注所属租户
18	 *   deptInfo          — 部门分组（当前租户/全部/有效/无效），每条部门标注所属租户
19	 * </pre>
20	 *
21	 * @author shy
22	 * @since 2026-06-11
23	 */
24	@Data
25	public class UserContextDTO {
26	
27	    /** 用户基本信息 */
28	    private UserInfo userInfo;
29	
30	    /** 租户分组（当前/全部/有效/无效） */
31	    private TenantGroup tenantInfo;
32	
33	    /** 权限汇总信息 */
34	    private PermissionInfo permInfo;
35	
36	    /** 角色分组（当前租户/全部/有效/无效），含租户标注 */
37	    private RoleGroup roleInfo;
38	
39	    /** 部门分组（当前租户/全部/有效/无效），含租户标注 */
40	    private DeptGroup deptInfo;
41	
