43	
44	    @Data
45	    public static class UserInfo {
46	        /** 用户ID */
47	        private Long userId;
48	        /** 用户编码 */
49	        private String userCode;
50	        /** 用户名（登录名） */
51	        private String userName;
52	        /** 昵称 */
53	        private String nickName;
54	        /** 邮箱 */
55	        private String email;
56	        /** 手机号 */
57	        private String phone;
58	        /** 头像URL */
59	        private String avatar;
60	    }
61	
62	    // ==================== 租户相关 ====================
63	
64	    @Data
65	    public static class TenantItem {
66	        /** 租户编码 */
67	        private String tenantCode;
68	        /** 租户名称 */
69	        private String tenantName;
70	        /** 租户状态（ENABLED/DISABLED/EXPIRED/PENDING） */
71	        private String status;
