172	    private UserContextDTO.PermissionInfo buildPermissionInfo(List<UserPermDTO> permList,
173	                                                               String currentTenantCode,
174	                                                               String currentTenantName) {
175	        UserContextDTO.PermissionInfo permissionInfo = new UserContextDTO.PermissionInfo();
176	
177	        // 按租户分组权限
178	        Map<String, List<UserContextDTO.PermItem>> permsByTenant = new LinkedHashMap<>();
179	        Map<String, String> tenantNames = new HashMap<>();
180	
181	        // 当前租户的启用/禁用权限
182	        List<UserContextDTO.PermItem> currentEnabled = new ArrayList<>();
183	        List<UserContextDTO.PermItem> currentDisabled = new ArrayList<>();
184	
185	        // 字段级权限（只保留当前租户）
186	        Map<String, UserContextDTO.TableFieldPermission> queryFieldMap = new HashMap<>();
187	        Map<String, UserContextDTO.TableFieldPermission> createFieldMap = new HashMap<>();
188	        Map<String, UserContextDTO.TableFieldPermission> updateFieldMap = new HashMap<>();
189	
190	        // 用于去重的集合（基于 permCode + tenantCode）
191	        Set<String> permDeduplicationSet = new LinkedHashSet<>();
192	
193	        // 遍历所有权限记录
194	        for (UserPermDTO perm : permList) {
195	            if (perm.getPermCode() == null || perm.getTenantCode() == null) {
196	                continue;
197	            }
198	
199	            String tenantCode = perm.getTenantCode();
200	            String tenantName = perm.getTenantName();
201	            tenantNames.putIfAbsent(tenantCode, tenantName);
202	
203	            // 构建权限项并去重
204	            String deduplicationKey = perm.getPermCode() + "_" + tenantCode;
205	            if (!permDeduplicationSet.contains(deduplicationKey)) {
206	                permDeduplicationSet.add(deduplicationKey);
207	
208	                UserContextDTO.PermItem item = new UserContextDTO.PermItem();
209	                item.setPermCode(perm.getPermCode());
210	                item.setPermName(perm.getPermName());
211	                item.setPermType(perm.getPermType());
212	                item.setTenantCode(tenantCode);
213	                item.setTenantName(tenantName);
214	                item.setPermPolicyStatus(perm.getPermPolicyStatus());
215	
216	                // 按租户分组
217	                permsByTenant.computeIfAbsent(tenantCode, k -> new ArrayList<>()).add(item);
218	
219	                // 当前租户的启用/禁用分组
220	                if (currentTenantCode.equals(tenantCode)) {
221	                    if ("ACTIVE".equals(perm.getPermPolicyStatus())) {
222	                        currentEnabled.add(item);
223	                    } else {
224	                        currentDisabled.add(item);
225	                    }
226	                }
227	            }
228	
229	            // 🔴 关键修复：字段级权限只处理当前租户
230	            if (!currentTenantCode.equals(tenantCode)) {
231	                continue;
232	            }
233	
234	            // 处理字段级权限
235	            processFieldPermissions(perm, queryFieldMap, createFieldMap, updateFieldMap);
236	        }
237	
238	        // 设置current（启用/禁用分组）
239	        UserContextDTO.CurrentPermissions current = new UserContextDTO.CurrentPermissions();
240	        current.setEnabled(currentEnabled);
241	        current.setDisabled(currentDisabled);
242	        permissionInfo.setCurrent(current);
243	
244	        // 设置all/valid/invalid（按租户分组）
245	        List<UserContextDTO.TenantPermissions> allTenantPerms = new ArrayList<>();
246	        List<UserContextDTO.TenantPermissions> validTenantPerms = new ArrayList<>();
247	        List<UserContextDTO.TenantPermissions> invalidTenantPerms = new ArrayList<>();
248	
249	        for (Map.Entry<String, List<UserContextDTO.PermItem>> entry : permsByTenant.entrySet()) {
250	            String tenantCode = entry.getKey();
251	            String tenantName = tenantNames.get(tenantCode);
252	            List<UserContextDTO.PermItem> perms = entry.getValue();
253	
254	            // all
255	            UserContextDTO.TenantPermissions allGroup = new UserContextDTO.TenantPermissions();
256	            allGroup.setTenantCode(tenantCode);
257	            allGroup.setTenantName(tenantName);
258	            allGroup.setPermissions(new ArrayList<>(perms));
259	            allTenantPerms.add(allGroup);
260	
261	            // valid/invalid分组
262	            List<UserContextDTO.PermItem> validPerms = new ArrayList<>();
263	            List<UserContextDTO.PermItem> invalidPerms = new ArrayList<>();
264	            for (UserContextDTO.PermItem perm : perms) {
265	                if ("ACTIVE".equals(perm.getPermPolicyStatus())) {
266	                    validPerms.add(perm);
267	                } else {
268	                    invalidPerms.add(perm);
269	                }
270	            }
271	
272	            if (!validPerms.isEmpty()) {
273	                UserContextDTO.TenantPermissions validGroup = new UserContextDTO.TenantPermissions();
274	                validGroup.setTenantCode(tenantCode);
275	                validGroup.setTenantName(tenantName);
276	                validGroup.setPermissions(validPerms);
277	                validTenantPerms.add(validGroup);
278	            }
279	
280	            if (!invalidPerms.isEmpty()) {
281	                UserContextDTO.TenantPermissions invalidGroup = new UserContextDTO.TenantPermissions();
282	                invalidGroup.setTenantCode(tenantCode);
283	                invalidGroup.setTenantName(tenantName);
284	                invalidGroup.setPermissions(invalidPerms);
285	                invalidTenantPerms.add(invalidGroup);
286	            }
287	        }
288	
289	        permissionInfo.setAll(allTenantPerms);
290	        permissionInfo.setValid(validTenantPerms);
291	        permissionInfo.setInvalid(invalidTenantPerms);
292	
293	        // 设置字段级权限（按租户分组，当前只有当前租户）
294	        Map<String, UserContextDTO.FieldPermission> fieldPermByTenant = new HashMap<>();
295	        UserContextDTO.FieldPermission fp = new UserContextDTO.FieldPermission();
296	        fp.setQuery(queryFieldMap);
